class Solution {
    public boolean isSelfCrossing(int[] d) {
        for (int i = 3; i < d.length; i++) {
            if (crossesFourthWithFirst(d, i)) return true;
            if (touchesFifthWithFirst(d, i)) return true;
            if (crossesSixthWithFirst(d, i)) return true;
        }
        return false;
    }

    private boolean crossesFourthWithFirst(int[] d, int i) {
        return d[i] >= d[i - 2] && d[i - 1] <= d[i - 3];
    }

    private boolean touchesFifthWithFirst(int[] d, int i) {
        return i >= 4 && d[i - 1] == d[i - 3] && d[i] + d[i - 4] >= d[i - 2];
    }

    private boolean crossesSixthWithFirst(int[] d, int i) {
        return i >= 5
            && d[i - 2] > d[i - 4]
            && d[i - 1] <= d[i - 3]
            && d[i - 1] + d[i - 5] >= d[i - 3]
            && d[i] + d[i - 4] >= d[i - 2];
    }
}

class Solution {
    public boolean isSelfCrossing(int[] distance) {
        int n = distance.length;
        long[][] segments = new long[n][4];
        long x = 0, y = 0;
        int[][] dirs = {{0, 1}, {-1, 0}, {0, -1}, {1, 0}};
        for (int i = 0; i < n; i++) {
            long nx = x + (long) dirs[i % 4][0] * distance[i];
            long ny = y + (long) dirs[i % 4][1] * distance[i];
            segments[i] = new long[]{x, y, nx, ny};
            for (int j = Math.max(0, i - 5); j <= i - 3; j++) {
                if (intersects(segments[i], segments[j])) return true;
            }
            x = nx;
            y = ny;
        }
        return false;
    }

    private boolean intersects(long[] a, long[] b) {
        long ax1 = Math.min(a[0], a[2]), ax2 = Math.max(a[0], a[2]);
        long ay1 = Math.min(a[1], a[3]), ay2 = Math.max(a[1], a[3]);
        long bx1 = Math.min(b[0], b[2]), bx2 = Math.max(b[0], b[2]);
        long by1 = Math.min(b[1], b[3]), by2 = Math.max(b[1], b[3]);
        return Math.max(ax1, bx1) <= Math.min(ax2, bx2)
            && Math.max(ay1, by1) <= Math.min(ay2, by2);
    }
}

class Solution {
    public boolean isSelfCrossing(int[] distance) {
        long[][] window = new long[6][4];
        long x = 0, y = 0;
        int[][] dirs = {{0, 1}, {-1, 0}, {0, -1}, {1, 0}};
        for (int i = 0; i < distance.length; i++) {
            long nx = x + (long) dirs[i % 4][0] * distance[i];
            long ny = y + (long) dirs[i % 4][1] * distance[i];
            long[] current = new long[]{x, y, nx, ny};
            for (int back = 3; back <= 5; back++) {
                if (i - back >= 0 && intersects(current, window[(i - back) % 6])) {
                    return true;
                }
            }
            window[i % 6] = current;
            x = nx;
            y = ny;
        }
        return false;
    }

    private boolean intersects(long[] a, long[] b) {
        long left = Math.max(Math.min(a[0], a[2]), Math.min(b[0], b[2]));
        long right = Math.min(Math.max(a[0], a[2]), Math.max(b[0], b[2]));
        long bottom = Math.max(Math.min(a[1], a[3]), Math.min(b[1], b[3]));
        long top = Math.min(Math.max(a[1], a[3]), Math.max(b[1], b[3]));
        return left <= right && bottom <= top;
    }
}

class Solution {
    public boolean isSelfCrossing(int[] distance) {
        if (distance.length < 4) return false;
        int[] d = distance.clone();
        int i = 2;
        while (i < d.length && d[i] > d[i - 2]) {
            i++;
        }
        if (i == d.length) return false;

        if ((i == 3 && d[i] == d[i - 2])
            || (i >= 4 && d[i] >= d[i - 2] - d[i - 4])) {
            d[i - 1] -= d[i - 3];
        }

        i++;
        while (i < d.length) {
            if (d[i] >= d[i - 2]) return true;
            i++;
        }
        return false;
    }
}

class Solution {
    public boolean isSelfCrossing(int[] distance) {
        int n = distance.length;
        int[] reversed = new int[n];
        for (int i = 0; i < n; i++) {
            reversed[i] = distance[n - 1 - i];
        }
        return hasLocalCrossing(reversed);
    }

    private boolean hasLocalCrossing(int[] d) {
        for (int i = 3; i < d.length; i++) {
            if (d[i] >= d[i - 2] && d[i - 1] <= d[i - 3]) return true;
            if (i >= 4 && d[i - 1] == d[i - 3] && d[i] + d[i - 4] >= d[i - 2]) return true;
            if (i >= 5
                && d[i - 2] > d[i - 4]
                && d[i - 1] <= d[i - 3]
                && d[i - 1] + d[i - 5] >= d[i - 3]
                && d[i] + d[i - 4] >= d[i - 2]) {
                return true;
            }
        }
        return false;
    }
}
